input.sparql:
SELECT ?ts ?point ?cls WHERE {
  ?point a brick:Zone ; brick:hasSubclass* ?sub .
} LIMIT 5

SELECT ?point ?cls ?ts WHERE {
  ?zone a brick:Zone ; rdfs:label "Core_mid".
} LIMIT 10

SELECT ?p ?ts WHERE {
  ?zone brick:hasPoint ?p .
  ?p a brick:Air_Temperature_Sensor .
} LIMIT 10

SELECT ?ts ?sid WHERE {
  ?zone ref:hasExternalReference ?e .
  ?e ref:hasTimeseriesId ?tid .
  ?p ref:hasExternalReference ?e .
  ?p a brick:Air_Temperature_Sensor .
} LIMIT 5

SELECT ?p ?type WHERE {
  ?zone a brick:Zone ; rdfs:label ?l .
  FILTER(CONTAINS(?l, "Core_mid"))
  ?zone brick:hasPoint ?p .
  OPTIONAL { ?p a ?type . }
} LIMIT 40

